using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class SaveTrike {public static string Main(){var t=Object.FindFirstObjectByType<TrikeController>();t.Movement.cargoLocationName="cargo bed";EditorUtility.SetDirty(t.Movement);PrefabUtility.RecordPrefabInstancePropertyModifications(t.Movement);PrefabUtility.ApplyPrefabInstance(t.gameObject,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(t.gameObject.scene);EditorSceneManager.SaveScene(t.gameObject.scene);Selection.activeGameObject=t.gameObject;if(SceneView.lastActiveSceneView!=null)SceneView.lastActiveSceneView.FrameSelected();return "Saved Trike cargo label, prefab and scene";}}
